import numpy as np
from scipy.optimize import fsolve

def find_solutions_precise():
    solutions = []
    for a_val in np.linspace(0.1, 1.0, 20):
        for b_val in np.linspace(0.1, 1.0, 20):
            def func(c_val):
                if c_val <= 0: return 1e9
                lhs = a_val/(4*a_val**2+1) + b_val/(4*b_val**2+1) + c_val/(4*c_val**2+1)
                rhs = 1/(8*(a_val+b_val)*(b_val+c_val)*(c_val+a_val))
                return lhs - rhs

            try:
                c_sol = fsolve(func, 0.5)[0]
                if c_sol > 0:
                    lhs = a_val/(4*a_val**2+1) + b_val/(4*b_val**2+1) + c_sol/(4*c_sol**2+1)
                    rhs = 1/(8*(a_val+b_val)*(b_val+c_sol)*(c_sol+a_val))
                    if abs(lhs - rhs) < 1e-8:
                        solutions.append((a_val, b_val, c_sol))
            except:
                pass

    for sol in solutions:
        a, b, c = sol
        s = a*b + b*c + c*a
        print(f"a={a:.6f}, b={b:.6f}, c={c:.6f}, sum_prod={s:.10f}")

