import numpy as np
from scipy.optimize import fsolve

def h(Z, X, Y):
    C = X/(X**2+1) + Y/(Y**2+1)
    return C + Z/(Z**2+1) - 2/((X+Y)*(Y+Z)*(Z+X))

# Search for X, Y such that h(Z) has multiple roots for Z > 0
for X in np.linspace(0.1, 5, 20):
    for Y in np.linspace(0.1, 5, 20):
        if X == Y: continue
        # Find roots of h(Z) in (0, 100)
        roots = []
        # Sample the function to find sign changes
        zs = np.linspace(0.001, 100, 1000)
        for i in range(len(zs)-1):
            if h(zs[i], X, Y) * h(zs[i+1], X, Y) < 0:
                root = fsolve(h, (zs[i]+zs[i+1])/2, args=(X, Y))[0]
                if root > 0:
                    roots.append(root)
        if len(roots) > 1:
            print(f"X={X}, Y={Y}, roots={roots}")

